with ps as (select user_id, jsonb_agg(jsonb_build_object('id', id, 'title', title)) as posts from posts group by user_id) select jsonb_build_object('posts', ps.posts) as a, (select jsonb_build_object('id', p1.id) from posts p1 where p1.user_id = u.id limit 1) as b1, (select jsonb_build_object('id', p2.id) from posts p2 where p2.user_id = u.id limit 1) as b2, (select jsonb_build_object('id', p3.id) from posts p3 where p3.user_id = u.id limit 1) as b3, (select jsonb_build_object('id', p4.id) from posts p4 where p4.user_id = u.id limit 1) as b4, (select jsonb_build_object('id', p5.id) from posts p5 where p5.user_id = u.id limit 1) as b5, (select jsonb_build_object('id', p6.id) from posts p6 where p6.user_id = u.id limit 1) as b6 from users u left join ps on ps.user_id = u.id
